import{c as e,Q as a,j as s,m as n}from"./chunks/framework.t4rEqR7d.js";const g=JSON.parse('{"title":"Desktop app","description":"","frontmatter":{},"headers":[],"relativePath":"desktop.md","filePath":"desktop.md"}'),o={name:"desktop.md"};function i(r,t,l,d,p,h){return a(),s("div",null,[...t[0]||(t[0]=[n(`<h1 id="desktop-app" tabindex="-1">Desktop app <a class="header-anchor" href="#desktop-app" aria-label="Permalink to &quot;Desktop app&quot;">​</a></h1><p>Language: <a href="/pagent/zh/desktop.html">中文</a> | English</p><p><strong>pagent Desktop</strong> is a desktop workbench for talking to an AI agent: session history on the left, chat in the center, sandbox files and generated artifacts on the right.</p><p>This page is for <strong>end users</strong> — download, API key, first task, everyday controls. To hack on the app itself, see the <a href="https://github.com/SyncLionPaw/pagent/blob/main/editors/desktop/README.md" target="_blank" rel="noreferrer">developer README</a>.</p><h2 id="install" tabindex="-1">Install <a class="header-anchor" href="#install" aria-label="Permalink to &quot;Install&quot;">​</a></h2><h3 id="_1-install-the-backend-required" tabindex="-1">1. Install the backend (required) <a class="header-anchor" href="#_1-install-the-backend-required" aria-label="Permalink to &quot;1. Install the backend (required)&quot;">​</a></h3><p>Desktop needs the <code>pagent</code> command on your machine (same as the VS Code extension):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tool</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pagent</span></span></code></pre></div><p>If the app later says it cannot start the backend, make sure <code>pagent</code> is on your <code>PATH</code>, or reinstall with the command above.</p><h3 id="_2-download-the-app" tabindex="-1">2. Download the app <a class="header-anchor" href="#_2-download-the-app" aria-label="Permalink to &quot;2. Download the app&quot;">​</a></h3><p>Get the desktop build from <a href="https://github.com/SyncLionPaw/pagent/releases" target="_blank" rel="noreferrer">pagent GitHub Releases</a>:</p><ul><li><strong>macOS (Apple Silicon)</strong> — <code>pagent-Desktop-&lt;version&gt;-arm64.zip</code>, or <code>pagent Desktop.app</code> inside the release assets.</li></ul><p>Unzip if needed, then move <strong>pagent Desktop</strong> into <strong>Applications</strong>.</p><div class="tip custom-block"><p class="custom-block-title">macOS first open</p><p>The <code>.app</code> is not notarized yet. If macOS blocks it, right-click the app → <strong>Open</strong> → confirm once. After that, double-click works normally.</p></div><p><strong>Windows / Linux builds</strong> are not published on Releases yet. On those platforms you can use the <a href="./vscode.html">VS Code extension</a> or the terminal (<code>pagent</code>).</p><h2 id="before-your-first-message-api-key" tabindex="-1">Before your first message: API key <a class="header-anchor" href="#before-your-first-message-api-key" aria-label="Permalink to &quot;Before your first message: API key&quot;">​</a></h2><p><strong>Desktop does not walk you through setup on first launch</strong> (the VS Code extension does).</p><p>Configure a provider key <strong>before</strong> chatting, using either method:</p><p><strong>Environment variable:</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> DEEPSEEK_API_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sk-...</span></span></code></pre></div><p><strong>Config file (recommended):</strong> create <code>~/.pagent/pagent.toml</code>:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">provider</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">api_key = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;sk-...&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">model = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;deepseek-v4-flash&quot;</span></span></code></pre></div><p>More providers: <a href="./guide/providers.html">Providers &amp; API keys</a>.</p><p>If the key is missing, you will see an error after you send a message. Open <strong>Settings</strong> (gear in the title bar) to check whether a config file exists — that panel is <strong>read-only</strong> and does not save changes for you.</p><h2 id="first-launch" tabindex="-1">First launch <a class="header-anchor" href="#first-launch" aria-label="Permalink to &quot;First launch&quot;">​</a></h2><ol><li>Open <strong>pagent Desktop</strong>.</li><li>The app starts the backend automatically and tries to <strong>resume your latest conversation</strong> for the current project.</li><li>To start fresh, click <strong>New task</strong> in the sidebar.</li></ol><h3 id="create-a-task" tabindex="-1">Create a task <a class="header-anchor" href="#create-a-task" aria-label="Permalink to &quot;Create a task&quot;">​</a></h3><p>In the <strong>New task</strong> dialog:</p><table tabindex="0"><thead><tr><th>Field</th><th>What to pick</th></tr></thead><tbody><tr><td><strong>Sandbox</strong></td><td><strong>local</strong> — runs on your Mac, no Docker needed (default)</td></tr><tr><td><strong>Project folder</strong></td><td>The folder on disk you want the agent to work with</td></tr></tbody></table><p>Click <strong>Create session</strong>, type in the box at the bottom, press <strong>Enter</strong> to send (<strong>Shift+Enter</strong> for a new line).</p><h2 id="main-window" tabindex="-1">Main window <a class="header-anchor" href="#main-window" aria-label="Permalink to &quot;Main window&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────┬──────────────────────┬─────────────┐</span></span>
<span class="line"><span>│  Sessions   │       Chat           │  Files &amp;    │</span></span>
<span class="line"><span>│             │                      │  artifacts  │</span></span>
<span class="line"><span>└─────────────┴──────────────────────┴─────────────┘</span></span></code></pre></div><ul><li><strong>Left</strong> — past chats; click one to continue.</li><li><strong>Center</strong> — messages, tool steps, composer.</li><li><strong>Right</strong> — sandbox tree, project files, outputs (HTML, PDF, etc.), log.</li></ul><p>Drag the edges to resize. Press <strong>⌘K</strong> (or the <strong>?</strong> button) for shortcuts.</p><h2 id="composer" tabindex="-1">Composer <a class="header-anchor" href="#composer" aria-label="Permalink to &quot;Composer&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Control</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Send / Stop</strong></td><td>Send; while the agent is running, becomes <strong>Stop</strong> to cancel</td></tr><tr><td><strong>Lightning (YOLO)</strong></td><td>Auto-approve tool calls — use only when you trust the task</td></tr><tr><td><strong>Ring</strong></td><td>Rough context usage vs model limit</td></tr><tr><td><strong>@</strong></td><td>Insert a file from your project or sandbox into the message</td></tr></tbody></table><h2 id="settings-help" tabindex="-1">Settings &amp; help <a class="header-anchor" href="#settings-help" aria-label="Permalink to &quot;Settings &amp; help&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Where</th><th>What</th></tr></thead><tbody><tr><td><strong>Gear</strong></td><td>View <code>~/.pagent/pagent.toml</code> (secrets shown as “configured”)</td></tr><tr><td><strong>Book icon</strong></td><td>Open this documentation site in the browser</td></tr><tr><td><strong>User menu → Scan docs</strong></td><td>QR code for the docs on your phone</td></tr></tbody></table><p>To change model or advanced sandbox options, edit <code>pagent.toml</code> in a text editor.</p><h2 id="where-files-go" tabindex="-1">Where files go <a class="header-anchor" href="#where-files-go" aria-label="Permalink to &quot;Where files go&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/.pagent/</span></span>
<span class="line"><span>├── pagent.toml       # your API key and model</span></span>
<span class="line"><span>├── threads/          # conversation history</span></span>
<span class="line"><span>└── skills/           # optional local skills</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&lt;your project&gt;/</span></span>
<span class="line"><span>└── artifacts/        # files the agent generated (HTML, etc.)</span></span></code></pre></div><p>Do not share or commit <code>pagent.toml</code> if it contains a real API key.</p><h2 id="something-wrong" tabindex="-1">Something wrong? <a class="header-anchor" href="#something-wrong" aria-label="Permalink to &quot;Something wrong?&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Problem</th><th>Try</th></tr></thead><tbody><tr><td>“Bridge” or backend won’t start</td><td>Run <code>uv tool install pagent</code>; check the log panel on the right</td></tr><tr><td>Error after sending</td><td>Add API key to <code>pagent.toml</code> or <code>DEEPSEEK_API_KEY</code></td></tr><tr><td>Settings says no config file</td><td>Create <code>~/.pagent/pagent.toml</code> as above</td></tr><tr><td>Tool stuck on “running”</td><td>Tap <strong>Stop</strong>, or send again; recent versions fix stale tool cards on reload</td></tr></tbody></table><h2 id="also-useful" tabindex="-1">Also useful <a class="header-anchor" href="#also-useful" aria-label="Permalink to &quot;Also useful&quot;">​</a></h2><ul><li><a href="./vscode.html">VS Code extension</a> — same agent inside VS Code, with guided first-run setup</li><li><a href="./guide/install.html">Install CLI</a> — if <code>uv</code> is not installed yet</li></ul>`,46)])])}const k=e(o,[["render",i]]);export{g as __pageData,k as default};
